const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { labelFor } = require('../labels/service.cjs');
test('each label request sees the latest on-disk configuration', () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(),'warehouse-labels-'));
  try {
    const filename = path.join(root,'labels.json');
    fs.writeFileSync(filename,JSON.stringify({prefix:'BIN',digits:3}));
    assert.equal(labelFor(filename,7),'BIN-007');
    fs.writeFileSync(filename,JSON.stringify({prefix:'RACK',digits:4}));
    assert.equal(labelFor(filename,7),'RACK-0007');
    assert.equal(labelFor(filename,12345),'RACK-12345');
    fs.writeFileSync(filename,JSON.stringify({prefix:'PALLET',digits:2}));
    assert.equal(labelFor(filename,0),'PALLET-00');
    fs.unlinkSync(filename);
    assert.throws(() => labelFor(filename,7),error => error.code === 'ENOENT');
    fs.writeFileSync(filename,JSON.stringify({prefix:'NEW',digits:1}));
    assert.equal(labelFor(filename,7),'NEW-7');
  } finally { fs.rmSync(root,{recursive:true,force:true}); }
});

